INSERT INTO "questionnaires" ("id", "company_id", "name", "purpose", "kind", "anonymous", "status", "origin") VALUES ('nr1-padrao', NULL, 'Equilibra NR-1 padrão', 'Avaliação de riscos psicossociais da NR-1: 28 itens em 7 dimensões, escala Nunca → Sempre.', 'nr1', true, 'active', 'system');--> statement-breakpoint
INSERT INTO "questionnaire_versions" ("id", "questionnaire_id", "version", "items") VALUES ('nr1-padrao-v1', 'nr1-padrao', 1, '[{"id": "d1", "text": "Preciso trabalhar muito rápido para dar conta das tarefas.", "type": "likert5", "dimension": "demandas", "risk": true}, {"id": "d2", "text": "Tenho prazos ou metas que não consigo cumprir na jornada normal.", "type": "likert5", "dimension": "demandas", "risk": true}, {"id": "d3", "text": "Levo trabalho para fora do horário ou faço horas extras para não atrasar.", "type": "likert5", "dimension": "demandas", "risk": true}, {"id": "d4", "text": "Consigo fazer pausas durante o dia quando preciso.", "type": "likert5", "dimension": "demandas", "risk": false}, {"id": "c1", "text": "Posso decidir como organizar o meu próprio trabalho.", "type": "likert5", "dimension": "controle", "risk": false}, {"id": "c2", "text": "Tenho voz nas decisões que afetam a minha rotina.", "type": "likert5", "dimension": "controle", "risk": false}, {"id": "c3", "text": "Consigo definir o ritmo em que trabalho.", "type": "likert5", "dimension": "controle", "risk": false}, {"id": "c4", "text": "Uso as minhas habilidades e conhecimentos no dia a dia.", "type": "likert5", "dimension": "controle", "risk": false}, {"id": "l1", "text": "Minha liderança me ajuda quando o trabalho fica difícil.", "type": "likert5", "dimension": "lideranca", "risk": false}, {"id": "l2", "text": "Recebo retorno claro e respeitoso sobre o meu trabalho.", "type": "likert5", "dimension": "lideranca", "risk": false}, {"id": "l3", "text": "Posso falar com a minha liderança sobre algo que me preocupa.", "type": "likert5", "dimension": "lideranca", "risk": false}, {"id": "l4", "text": "Sou cobrado(a) de forma agressiva ou humilhante.", "type": "likert5", "dimension": "lideranca", "risk": true}, {"id": "p1", "text": "Meus colegas me ajudam quando preciso.", "type": "likert5", "dimension": "colegas", "risk": false}, {"id": "p2", "text": "Existe espírito de cooperação na minha equipe.", "type": "likert5", "dimension": "colegas", "risk": false}, {"id": "p3", "text": "Me sinto parte da equipe.", "type": "likert5", "dimension": "colegas", "risk": false}, {"id": "p4", "text": "Há disputas ou competição prejudicial entre colegas.", "type": "likert5", "dimension": "colegas", "risk": true}, {"id": "r1", "text": "Presencio ou sofro gritos, ofensas ou ameaças no trabalho.", "type": "likert5", "dimension": "relacoes", "risk": true}, {"id": "r2", "text": "Sou isolado(a), ignorado(a) ou excluído(a) de propósito.", "type": "likert5", "dimension": "relacoes", "risk": true}, {"id": "r3", "text": "Recebo comentários ou investidas de cunho sexual indesejados.", "type": "likert5", "dimension": "relacoes", "risk": true}, {"id": "r4", "text": "Sinto medo de represália se eu relatar um problema.", "type": "likert5", "dimension": "relacoes", "risk": true}, {"id": "a1", "text": "Sei exatamente o que se espera de mim no trabalho.", "type": "likert5", "dimension": "papel", "risk": false}, {"id": "a2", "text": "Minhas responsabilidades estão bem definidas.", "type": "likert5", "dimension": "papel", "risk": false}, {"id": "a3", "text": "Recebo pedidos contraditórios de pessoas diferentes.", "type": "likert5", "dimension": "papel", "risk": true}, {"id": "a4", "text": "Entendo como o meu trabalho contribui para a empresa.", "type": "likert5", "dimension": "papel", "risk": false}, {"id": "e1", "text": "Meu esforço é reconhecido.", "type": "likert5", "dimension": "reconhecimento", "risk": false}, {"id": "e2", "text": "Sou informado(a) com antecedência sobre mudanças que me afetam.", "type": "likert5", "dimension": "reconhecimento", "risk": false}, {"id": "e3", "text": "Considero a minha remuneração justa pelo trabalho que faço.", "type": "likert5", "dimension": "reconhecimento", "risk": false}, {"id": "e4", "text": "Me sinto inseguro(a) sobre o meu futuro na empresa.", "type": "likert5", "dimension": "reconhecimento", "risk": true}]'::jsonb);--> statement-breakpoint
